content.text:
The root cause is a single application exception in ts-route-service, and its errors spread to users through travel, travel2, basic and food.

```json
{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "application_exception",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name LIKE 'GET /api/v1/routeservice/routes/{routeId}%' GROUP BY 1,2,3,4", "claim": "Every GET /routes/{routeId} server span on ts-route-service ends in Error with HTTP 500 in the abnormal window (15,035 of them)."},
        {"kind": "log", "sql": "SELECT service_name, attr_k8s_pod_name, level, count(*) n FROM abnormal_logs WHERE message LIKE '%IllegalArgumentException: Invalid argument%' GROUP BY 1,2,3", "claim": "ts-route-service logs 15,035 SEVERE 'IllegalArgumentException: Invalid argument' dispatcher exceptions, none in the normal period."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name IN ('RouteController.queryById','BasicErrorController.error') GROUP BY 1,2", "claim": "The exception is raised inside RouteController.queryById, which returns Error, and then the error controller handles it."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-route-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name, c.span_name, c.attr_status_code, count(*) n, round(avg(c.duration)/1e6,1) avg_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel-service' AND c.service_name='ts-route-service' GROUP BY 1,2,3", "claim": "Travel-service calls to route-service's routes/{routeId} return Error with 500s and travel's own server spans slow to about 3.6 s."}]},
    {"from": "ts-route-service", "to": "ts-travel2-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name, c.span_name, c.attr_status_code, count(*) n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel2-service' AND c.service_name='ts-route-service' GROUP BY 1,2,3", "claim": "Route-service calls from travel2-service fail with Error status in the abnormal window."}]},
    {"from": "ts-route-service", "to": "ts-basic-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name, c.span_name, c.attr_status_code, count(*) n, round(avg(c.duration)/1e6,1) avg_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-basic-service' AND c.service_name='ts-route-service' GROUP BY 1,2,3", "claim": "Basic-service calls to route-service return Error; basic's POST /basic/travel server spans fail with avg 620 ms."}]},
    {"from": "ts-travel-service", "to": "ts-food-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name, c.span_name, c.attr_status_code, count(*) n, round(avg(p.duration)/1e6,1) food_parent_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-food-service' AND c.service_name='ts-travel-service' GROUP BY 1,2,3", "claim": "Food-service calls to travel-service's routes/{tripId} are slow and time out at 60 s, making food's getAllFood slow."}]},
    {"from": "ts-food-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-food-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "Food-service's food-list server spans reach 60 s p95 with Error status, versus about 113 ms p95 in normal."}]}
  ]
}
```

